class Account:
    def __init__(self, owner, overdraft_limit=0):
        if not isinstance(owner, str) or not owner.strip():
            raise ValueError("Owner required")
        if type(overdraft_limit) is not int or overdraft_limit < 0:
            raise ValueError("Overdraft limit cannot be negative")
        self._owner = owner
        self._limit = overdraft_limit
        self._balance = 0
        self._frozen = False
        self._history = []

    @property
    def owner(self):
        return self._owner

    @property
    def balance(self):
        return self._balance

    @property
    def frozen(self):
        return self._frozen

    @property
    def history(self):
        return list(self._history)

    def freeze(self):
        self._frozen = True

    def unfreeze(self):
        self._frozen = False

    @staticmethod
    def _check_amount(amount):
        if type(amount) is not int or amount < 1:
            raise ValueError("Amount must be positive")

    def _check_active(self):
        if self._frozen:
            raise ValueError("Account is frozen")

    def _apply(self, kind, delta):
        self._balance += delta
        self._history.append((kind, abs(delta), self._balance))

    def deposit(self, amount):
        self._check_active()
        self._check_amount(amount)
        self._apply("deposit", amount)

    def withdraw(self, amount):
        self._check_active()
        self._check_amount(amount)
        if self._balance - amount < -self._limit:
            raise ValueError("Insufficient funds")
        self._apply("withdraw", -amount)

    def transfer(self, target, amount):
        if target is self:
            raise ValueError("Cannot transfer to the same account")
        self._check_active()
        target._check_active()
        self._check_amount(amount)
        if self._balance - amount < -self._limit:
            raise ValueError("Insufficient funds")
        self._apply("transfer_out", -amount)
        target._apply("transfer_in", amount)
